<template><div class="page"><div class="chat-layout"><aside class="chat-list"><n-button type="primary" block @click="chat.newSession">新建会话</n-button><div v-for="s in chat.sessions" :key="s.id" :class="['chat-session',{active:s.id===chat.activeId}]" @click="chat.select(s.id)">{{s.title}}</div></aside><section class="chat-main"><div class="messages"><n-empty v-if="!active?.messages.length" description="开始向 AutoOps Agent 提问"/><div v-for="(m,i) in active?.messages||[]" :key="i" :class="['message',m.role]">{{m.content}}<span v-if="chat.streaming&&i===active.messages.length-1">▍</span></div></div><div class="chat-input"><n-input v-model:value="input" type="textarea" :autosize="{minRows:1,maxRows:4}" placeholder="描述你的运维问题..." @keydown.enter.exact.prevent="send"/><n-button type="primary" :loading="chat.streaming" @click="send">发送</n-button></div></section></div></div></template>
<script setup>import {ref,computed,onMounted} from 'vue';import {useRoute} from 'vue-router';import {useChatStore} from '@/stores/chat';const route=useRoute(),chat=useChatStore(),input=ref(''),active=computed(()=>chat.active);onMounted(()=>{if(!chat.sessions.length)chat.newSession();if(route.query.prompt)input.value=route.query.prompt});async function send(){const q=input.value.trim();if(!q||chat.streaming)return;input.value='';await chat.send(q)}</script>
